function formatBytes(bytes) {
  if (!Number.isFinite(bytes) || bytes < 0) return '확인할 수 없음';
  const units = ['B', 'KiB', 'MiB', 'GiB'];
  let n = bytes, i = 0;
  while (n >= 1024 && i < units.length - 1) { n /= 1024; i++; }
  return `${i ? n.toFixed(1) : n} ${units[i]}`;
}

$('#backup-open').onclick = () => {
  modal(`<div class="modal-head"><h2>백업과 복원</h2><button class="close" aria-label="닫기">×</button></div>
    <p class="help">현재 보관함의 데이터베이스와 등록된 PDF를 함께 보관합니다. 프로젝트, 읽기 기록, 발췌와 메모가 포함되므로 백업 파일을 안전한 곳에 보관하세요.</p>
    <p class="help">현재 한도: PDF 최대 10,000개, 압축 전 데이터베이스와 PDF 합계 약 2 GiB, 백업 ZIP 최대 1 GiB. 파일 크기와 저장 공간에 따라 시간이 걸릴 수 있습니다.</p>
    <div id="backup-create-result" aria-live="polite"></div>
    <div class="actions"><button class="primary" id="backup-start">백업 만들기</button></div>
    <hr style="border:0;border-top:1px solid #e1e7e2;margin:22px 0">
    <h3>백업 확인과 복원</h3>
    <p class="help">먼저 파일 내용과 무결성을 확인합니다. 복원하면 검증된 사본이 별도 폴더에 만들어지며 현재 보관함을 덮어쓰지 않습니다.</p>
    <label class="label" for="backup-file">EasyResearch 백업 ZIP</label><input id="backup-file" type="file" accept=".zip,application/zip">
    <div class="actions"><button class="secondary" id="backup-inspect" disabled>선택한 백업 확인</button><button class="secondary" id="backup-restore" disabled>별도 폴더에 복원</button></div>
    <div id="backup-inspect-result" aria-live="polite"></div><div id="backup-restore-result" aria-live="polite"></div>`);
  const root = $('#modal-content');
  const create = $('#backup-start', root), fileInput = $('#backup-file', root);
  const inspect = $('#backup-inspect', root), restore = $('#backup-restore', root);
  const createResult = $('#backup-create-result', root), inspectResult = $('#backup-inspect-result', root), restoreResult = $('#backup-restore-result', root);
  let verifiedFile = null;
  const setBusy = busy => { fileInput.disabled = busy; inspect.disabled = busy || !fileInput.files.length; restore.disabled = busy || !verifiedFile; };
  create.onclick = async () => {
    create.disabled = true;
    createResult.innerHTML = '<div class="notice">백업을 만들고 검증하고 있습니다. 잠시 기다려 주세요.</div>';
    try {
      const r = await post('/api/backups', {});
      const link = typeof r.download_url === 'string' && /^\/api\/backups\/[0-9a-f-]+\/download$/.test(r.download_url) ? `<a href="${esc(r.download_url)}" download>백업 ZIP 다운로드</a>` : '';
      createResult.innerHTML = `<div class="notice">백업 생성 및 파일 검증 완료 · PDF ${esc(r.file_count)}개<br>${link || '다운로드 주소를 확인할 수 없습니다.'}<br>다운로드해 별도의 안전한 위치에도 보관하세요.</div>`;
    } catch (err) { createResult.innerHTML = `<div class="notice error">백업을 만들지 못했습니다. ${esc(err.message)} 저장 공간과 PDF 원본을 확인한 후 다시 시도하세요.</div>`; }
    finally { create.disabled = false; }
  };
  fileInput.onchange = () => { verifiedFile = null; inspectResult.innerHTML = ''; restoreResult.innerHTML = ''; setBusy(false); };
  inspect.onclick = async () => {
    const file = fileInput.files[0]; if (!file) return;
    verifiedFile = null; restoreResult.innerHTML = ''; setBusy(true);
    inspectResult.innerHTML = '<div class="notice">백업 내용을 확인하고 있습니다. 파일이 크면 시간이 걸릴 수 있습니다.</div>';
    const form = new FormData(); form.append('file', file);
    try {
      const r = await api('/api/backups/inspect', {method:'POST', body:form});
      if (r.status !== 'verified') throw new Error('백업 검증이 완료되지 않았습니다.');
      verifiedFile = file;
      const migration = r.requires_migration ? `<br>복원할 때 데이터 사본을 버전 ${esc(r.target_database_version)}으로 이관합니다. 백업 원본은 변경하지 않습니다.` : '';
      inspectResult.innerHTML = `<div class="notice"><strong>백업 확인 완료</strong><br>선택한 ZIP: ${esc(file.name)} (${esc(formatBytes(file.size))})<br>프로젝트 ${esc(r.project_count)}개 · 논문 ${esc(r.paper_count)}개 · 근거 ${esc(r.evidence_count)}개<br>PDF ${esc(r.file_count)}개 · PDF 크기 ${esc(formatBytes(r.total_file_bytes))}<br>백업 형식 ${esc(r.format)} · 데이터 버전 ${esc(r.database_version)}${migration}<br>확인 과정은 현재 보관함을 변경하지 않습니다.</div>`;
    } catch (err) { inspectResult.innerHTML = `<div class="notice error">백업을 확인하지 못했습니다. ${esc(err.message)} 올바른 EasyResearch 백업 파일인지 확인하세요.</div>`; }
    finally { setBusy(false); }
  };
  restore.onclick = async () => {
    const file = verifiedFile; if (!file) return;
    setBusy(true);
    restoreResult.innerHTML = '<div class="notice">백업을 다시 검증하고 별도 폴더에 복원하고 있습니다.</div>';
    const form = new FormData(); form.append('file', file);
    try {
      const r = await api('/api/backups/restore', {method:'POST', body:form});
      if (r.status !== 'verified' || typeof r.restore_path !== 'string') throw new Error('복원 결과를 확인할 수 없습니다.');
      const path = r.restore_path;
      restoreResult.innerHTML = `<div class="notice"><strong>별도 폴더 복원 완료</strong><br>PDF ${esc(r.file_count)}개 · 현재 보관함은 그대로 유지됩니다.<br>복원 번호: ${esc(r.id)}<br><label class="label" for="restore-path">복원 위치</label><input id="restore-path" type="text" readonly value="${esc(path)}"><p>복원본은 자동으로 열리지 않습니다. 현재 앱을 종료한 뒤 프로젝트 폴더의 <strong>복원 보관함 열기.cmd</strong>를 실행하고 복원 번호를 확인해 목록에서 선택하세요. 복원본에서 새로 기록한 내용은 현재 보관함과 별도로 저장됩니다.</p><p>원래 보관함으로 돌아가려면 복원본의 실행 창을 닫고 시작 파일을 평소처럼 다시 열면 됩니다.</p></div>`;
    } catch (err) { restoreResult.innerHTML = `<div class="notice error">복원하지 못했습니다. ${esc(err.message)} 백업 파일과 저장 공간을 확인하세요. 현재 보관함은 변경되지 않았습니다.</div>`; }
    finally { setBusy(false); }
  };
};
$('#content').addEventListener('click',e=>{const ideaEdit=e.target.closest('[data-edit-idea]');if(ideaEdit){const item=state.ideas.find(i=>i.id===ideaEdit.dataset.editIdea);if(item)ideaDialog(item).catch(error)}const ideaDelete=e.target.closest('[data-delete-idea]');if(ideaDelete){const item=state.ideas.find(i=>i.id===ideaDelete.dataset.deleteIdea);if(item)deleteIdeaDialog(item)}const paper=e.target.closest('[data-paper]');if(paper)openPaper(paper.dataset.paper);const page=e.target.closest('[data-page]');if(page){const number=Number(page.dataset.page);patchPaper(state.paper.id,{project_id:state.projectId,last_page:number-1}).then(()=>{state.paper.last_page=number-1;state.page=number;renderReader()}).catch(error)}const history=e.target.closest('[data-search-history]');if(history){const run=state.searchHistory[Number(history.dataset.searchHistory)];state.results=run.results||[];$('#search-query').value=run.query;$('#search-source').value=run.source;renderSearchResults(run.source);if(run.status!=='completed')notify(`이전 검색 실패: ${run.error||'원인 확인 필요'}`,'warning')}const edit=e.target.closest('[data-edit-evidence]');if(edit)editEvidence(edit.dataset.editEvidence);const add=e.target.closest('[data-add-result]');if(add)addResult(Number(add.dataset.addResult),add);const source=e.target.closest('[data-open-evidence-paper]');if(source)openPaper(source.dataset.openEvidencePaper,Number(source.dataset.evidencePage))});
function parsePaperHash(hash){
  const match=/^#\/paper\/([^?#]+)(?:\?([^#]*))?$/.exec(String(hash||''));
  if(!match)return null;
  let paperId='';try{paperId=decodeURIComponent(match[1])}catch{return {error:'링크의 논문 번호를 읽을 수 없습니다.'}}
  const params=new URLSearchParams(match[2]||''),projectId=params.get('project')||'',raw=params.get('page');
  if(!paperId||!projectId)return {error:'링크에 프로젝트와 논문 정보가 필요합니다.'};
  let page=null;
  if(raw!==null){if(!/^[1-9]\d*$/.test(raw)||!Number.isSafeInteger(Number(raw)))return {error:'링크의 페이지 번호는 1 이상의 정수여야 합니다.'};page=Number(raw)}
  return {paperId,projectId,page};
}
async function openDeepLink(hash){
  const link=parsePaperHash(hash);if(!link)return;
  if(link.error){notify(link.error,'error');return}
  if(!state.projects.some(p=>p.id===link.projectId))await refreshProjects();
  if(!state.projects.some(p=>p.id===link.projectId)){notify('링크의 프로젝트를 찾을 수 없습니다. 삭제되었거나 휴지통에 있을 수 있습니다.','error');return}
  if(state.projectId!==link.projectId){
    if(state.paper)import('/assets/pdf-viewer.js').then(v=>v.closePdfViewer());
    state.projectId=link.projectId;localStorage.setItem('easyresearch-project',link.projectId);state.paper=null;syncProjects();
  }
  state.view='library';state.paper=null;
  await render();
  const paper=state.papers.find(p=>String(p.id)===link.paperId);
  if(!paper){notify('이 프로젝트에서 해당 논문을 찾을 수 없습니다.','error');return}
  await openPaper(link.paperId,link.page);
}
function shortcutDialog(){modal(`<div class="modal-head"><h2>키보드 단축키</h2><button class="close" aria-label="닫기">×</button></div><ul class="help"><li><kbd>←</kbd> · <kbd>→</kbd> 논문 화면에서 이전·다음 페이지로 이동</li><li><kbd>?</kbd> 이 단축키 목록 열기</li></ul><p class="help">입력 칸에 커서가 있거나 다른 창이 열려 있을 때는 단축키가 동작하지 않습니다.</p>`)}
function readerKeyHandler(e){
  if(e.defaultPrevented||e.ctrlKey||e.metaKey||e.altKey)return;
  const t=e.target,tag=t?.tagName||'';
  if(t?.isContentEditable||/^(INPUT|TEXTAREA|SELECT)$/.test(tag))return;
  if(document.querySelector('dialog[open]'))return;
  if(e.key==='?'){e.preventDefault();shortcutDialog();return}
  if(!state.paper)return;
  const control=e.key==='ArrowLeft'?'#prev-page':e.key==='ArrowRight'?'#next-page':null;
  if(!control)return;
  const button=$(control);if(!button||button.disabled)return;
  e.preventDefault();button.click();
}
document.addEventListener('keydown',readerKeyHandler);
window.addEventListener('hashchange',()=>{openDeepLink(location.hash).catch(error)});
(async()=>{try{const health=await api('/api/health');state.workspaceScope=/^[a-f0-9]{64}$/.test(health.workspace_scope||'')?health.workspace_scope:null;$('#connection').textContent='로컬 서버 연결됨';await refreshProjects();await render();await openDeepLink(location.hash).catch(error)}catch(err){$('.status-dot').classList.add('offline');$('#connection').textContent='서버 연결 확인 필요';error(err);showLibrary()}})();



